package local.quiettv.launcher;

import android.content.BroadcastReceiver;
import android.content.Context;
import android.content.Intent;
import android.content.SharedPreferences;
import android.os.Build;
import android.os.UserManager;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.OutputStreamWriter;
import java.util.Map;
import java.util.Set;
import java.util.HashSet;

/** ADB maintenance only: guarded by the platform DUMP permission, never starts UI. */
public final class LocalMaintenanceReceiver extends BroadcastReceiver {
    @Override public void onReceive(final Context context,Intent intent){
        if(intent==null)return;UserManager user=(UserManager)context.getSystemService(Context.USER_SERVICE);if(Build.VERSION.SDK_INT>=24&&user!=null&&!user.isUserUnlocked())return;
        String action=intent.getAction();
        try{
            if("local.quiettv.launcher.EXPORT_STATE".equals(action)){JSONObject root=new JSONObject();for(String name:new String[]{"home","weather","playback_history"})root.put(name,export(context.getSharedPreferences(name,Context.MODE_PRIVATE)));write(context,"quiettv-state-backup.json",root);}
            else if("local.quiettv.launcher.IMPORT_STATE".equals(action)){File file=new File(context.getExternalFilesDir(null),"quiettv-state-backup.json");if(!file.isFile()||file.length()>262144)return;byte[] bytes=new byte[(int)file.length()];try(FileInputStream input=new FileInputStream(file)){int offset=0,n;while(offset<bytes.length&&(n=input.read(bytes,offset,bytes.length-offset))>0)offset+=n;if(offset!=bytes.length)return;}JSONObject root=new JSONObject(new String(bytes,"UTF-8"));JSONObject home=root.optJSONObject("home"),weather=root.optJSONObject("weather"),history=root.optJSONObject("playback_history");if(home==null||weather==null||history==null||!valid(home,"home")||!valid(weather,"weather")||!valid(history,"playback_history"))return;normalizeWallpaperBackup(context,home);importStores(context,new JSONObject[]{home,weather,history});GenericMediaHistory.changed(context);}
            else if("local.quiettv.launcher.EXTRAS_STATUS".equals(action))status(context);
            else if("local.quiettv.launcher.MEDIA_REBIND".equals(action)){GenericMediaHistory.rebind(context);status(context);}
            else if("local.quiettv.launcher.WEATHER_SETUP".equals(action)){
                // Service terms must be accepted in the visible settings UI.
                if(!"manual".equals(intent.getStringExtra("mode")))return;
                WeatherRepository repo=new WeatherRepository(context,()->{});
                try{if(!repo.consented())return;status(context);}finally{repo.dispose();}
            }
        }catch(Exception ignored){}
    }
    private static void status(Context c) throws Exception {
        JSONObject j=new JSONObject();SharedPreferences weather=c.getSharedPreferences("weather",Context.MODE_PRIVATE);HistoryStore history=new HistoryStore(c);j.put("version",c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName);j.put("api",android.os.Build.VERSION.SDK_INT);j.put("manufacturer",android.os.Build.MANUFACTURER);j.put("model",android.os.Build.MODEL);j.put("lowRam",((android.app.ActivityManager)c.getSystemService(Context.ACTIVITY_SERVICE)).isLowRamDevice());j.put("historyCount",history.list().size());j.put("historyEnabled",history.enabled());j.put("musicHistoryEnabled",history.musicEnabled());int music=0;for(PlaybackRecord r:history.list())if(r.apple())music++;j.put("musicHistoryCount",music);j.put("genericHistoryEnabled",history.genericEnabled());j.put("notificationAccess",GenericMediaHistory.permission(c));j.put("mediaListenerConnected",MediaHistoryService.active);j.put("mediaListenerSupported",!GenericMediaHistory.lowRamListenerUnsupported(c));j.put("watchNextProviderAvailable",c.getPackageManager().resolveContentProvider("android.media.tv",0)!=null);int generic=0;for(PlaybackRecord r:history.list())if(r.generic())generic++;j.put("genericHistoryCount",generic);j.put("activeSessionCount",GenericMediaHistory.sessions(c).size());j.put("weatherEnabled",weather.getBoolean("enabled",false));j.put("weatherConsent",weather.getString("consent",""));
        try{JSONObject cache=new JSONObject(weather.getString("cache","{}"));j.put("weatherCached",cache.has("temperature"));j.put("weatherUpdated",cache.optLong("updated"));JSONObject place=cache.optJSONObject("place");if(place!=null)j.put("weatherCity",place.optString("name"));}catch(Exception ignored){j.put("weatherCached",false);}write(c,"extras-status.json",j);
    }
    private static JSONObject export(SharedPreferences prefs) throws Exception {JSONObject root=new JSONObject();for(Map.Entry<String,?> entry:prefs.getAll().entrySet()){Object value=entry.getValue();JSONObject item=new JSONObject();String type=value instanceof Set?"set":value instanceof Integer?"int":value instanceof Long?"long":value instanceof Float?"float":value instanceof Boolean?"boolean":"string";item.put("type",type);if(value instanceof Set){JSONArray a=new JSONArray();for(Object v:(Set<?>)value)a.put(String.valueOf(v));item.put("value",a);}else item.put("value",value);root.put(entry.getKey(),item);}return root;}
    private static boolean valid(JSONObject root,String store){try{java.util.Iterator<String> keys=root.keys();while(keys.hasNext()){String key=keys.next();JSONObject item=root.getJSONObject(key);String type=item.getString("type");Object value=item.get("value");if("set".equals(type)){JSONArray a=item.getJSONArray("value");if(a.length()>4096)return false;for(int i=0;i<a.length();i++)if(!(a.get(i) instanceof String))return false;}else if("int".equals(type))item.getInt("value");else if("long".equals(type))item.getLong("value");else if("float".equals(type))item.getDouble("value");else if("boolean".equals(type))item.getBoolean("value");else if("string".equals(type)){if(!(value instanceof String)||((String)value).length()>262144)return false;}else return false;}if("playback_history".equals(store)&&root.has("records")){JSONObject records=root.getJSONObject("records");if(!"string".equals(records.optString("type")))return false;JSONArray list=new JSONArray(records.getString("value"));if(list.length()>8)return false;for(int i=0;i<list.length();i++)if(!PlaybackRecordFromJson.valid(list.optJSONObject(i)))return false;}if("home".equals(store)&&root.has("favorites")){JSONObject favorites=root.getJSONObject("favorites");if(!"set".equals(favorites.optString("type"))||favorites.getJSONArray("value").length()>4096)return false;}return true;}catch(Exception e){return false;}}
    private static void importStores(Context c,JSONObject[] incoming) throws Exception {String[] names={"home","weather","playback_history"};SharedPreferences[] stores=new SharedPreferences[names.length];JSONObject[] previous=new JSONObject[names.length];for(int i=0;i<names.length;i++){stores[i]=c.getSharedPreferences(names[i],Context.MODE_PRIVATE);previous[i]=export(stores[i]);}try{for(int i=0;i<names.length;i++)restore(stores[i],incoming[i]);}catch(Exception failure){for(int i=0;i<names.length;i++)try{restore(stores[i],previous[i]);}catch(Exception ignored){}throw failure;}}
    private static void normalizeWallpaperBackup(Context c,JSONObject home){try{JSONObject kindItem=home.optJSONObject("wallpaper_kind");if(kindItem==null)return;String kind=kindItem.optString("value","builtin");if(!kind.equals("image")&&!kind.equals("video"))return;JSONObject pathItem=home.optJSONObject("wallpaper_path");String path=pathItem==null?"":pathItem.optString("value","");File file=new File(path);File root=c.getExternalFilesDir("backgrounds");if(root==null)root=new File(c.getFilesDir(),"backgrounds");String base=root.getCanonicalPath()+File.separator,canonical=file.getCanonicalPath();boolean safe=file.isFile()&&canonical.startsWith(base)&&file.length()>0&&(kind.equals("video")?Wallpapers.video(file):Wallpapers.picture(file))&&file.length()<=WallpaperImportPolicy.limit(file.getName().substring(file.getName().lastIndexOf('.')+1).toLowerCase(java.util.Locale.ROOT));if(!safe){kindItem.put("value","builtin");home.remove("wallpaper_path");}}catch(Exception ignored){try{home.getJSONObject("wallpaper_kind").put("value","builtin");home.remove("wallpaper_path");}catch(Exception ignoredAgain){}}}
    private static final class PlaybackRecordFromJson {static boolean valid(JSONObject value){if(value==null)return false;try{PlaybackRecord record=new PlaybackRecord();record.source=value.optString("source",PlaybackRecord.PACKAGE);record.sourceLabel=value.optString("source_label");record.routeId=value.optString("route_id");record.routeChannel=value.optString("route_channel","0");record.contentId=value.optString("content_id");record.audio=value.optBoolean("audio");record.positionKnown=value.optBoolean("position_known",true);record.startedAt=value.optLong("started_at");record.album=value.optString("album");record.videoId=value.optString("id");record.episodeId=value.optString("eid");record.title=value.optString("title");record.episode=value.optString("episode");record.cover=value.optString("cover");record.command=value.optString("command");record.position=value.optLong("position");record.duration=value.optLong("duration");record.updated=value.optLong("updated");record.metadataAt=value.optLong("metadata_at");return record.valid();}catch(Exception e){return false;}}}
    private static void restore(SharedPreferences prefs,JSONObject root) throws Exception {SharedPreferences.Editor e=prefs.edit().clear();java.util.Iterator<String> keys=root.keys();while(keys.hasNext()){String key=keys.next();JSONObject item=root.getJSONObject(key);String type=item.getString("type");if("set".equals(type)){JSONArray a=item.getJSONArray("value");HashSet<String> values=new HashSet<>();for(int i=0;i<a.length();i++)values.add(a.getString(i));e.putStringSet(key,values);}else if("int".equals(type))e.putInt(key,item.getInt("value"));else if("long".equals(type))e.putLong(key,item.getLong("value"));else if("float".equals(type))e.putFloat(key,(float)item.getDouble("value"));else if("boolean".equals(type))e.putBoolean(key,item.getBoolean("value"));else if("string".equals(type))e.putString(key,item.getString("value"));}if(!e.commit())throw new java.io.IOException("Preference restore failed");}
    private static void write(Context c,String name,JSONObject j) throws Exception {File dir=c.getExternalFilesDir(null);if(dir==null)return;File target=new File(dir,name),tmp=new File(dir,name+".tmp");try(OutputStreamWriter out=new OutputStreamWriter(new FileOutputStream(tmp),"UTF-8")){out.write(j.toString());}if(!tmp.renameTo(target))throw new java.io.IOException("Cannot save status");}
}
